package dev.jun.gyeot;

import android.content.Context;
import android.database.Cursor;
import android.net.Uri;
import android.os.ParcelFileDescriptor;
import android.provider.DocumentsContract;
import android.util.AtomicFile;
import dev.jun.gyeot.core.FileOrganizationPlan;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.*;
import org.json.JSONObject;

/** Streamed, private-first generated media export (and memory backups in 백업). No MediaStore fallback or user-file deletion. */
final class SharedMediaOutput {
    static final String DIRECTORY = "pending-media-exports-v1";
    /** Up to 2GB: a video to upload (YouTube) can be long. */
    static final long MAX_BYTES = 2048L * 1024 * 1024;
    /** 마이튜브's captures while a video plays: their own folder in the 들퍼레 folder. */
    static final String CAPTURES = "마이튜브 캡처";
    /** 마이튜브's MP3s (YouTubeAudio): their own folder in the 들퍼레 folder too. */
    static final String AUDIO = "마이튜브 오디오";
    private SharedMediaOutput() {}

    static synchronized Uri save(Context context, String key, String category, String name, String mime, byte[] bytes, Runnable guard) throws Exception {
        return save(context,key,category,name,mime,new ByteArrayInputStream(bytes),guard);
    }
    /** The caller owns source. It must be generated bytes or an already-authorized private asset. */
    static synchronized Uri save(Context context, String key, String category, String name, String mime, InputStream source, Runnable guard) throws Exception {
        validate(category,name,mime); String id=id(key); File dir=directory(context), record=new File(dir,id+".json"), body=new File(dir,id+".data");
        guard.run();
        if(record.exists() || new File(record+".bak").exists()) {
            JSONObject state=read(record); validateState(state,id);
            if(!category.equals(state.getString("category")) || !mime.equals(state.getString("mime"))) throw new IOException("같은 저장 작업의 파일 종류가 달라 재사용하지 않았어요.");
            // A repeated source must match the original private staging receipt, never just its name.
            if(!digest(source,guard).equals(state.getString("sha256"))) throw new IOException("같은 저장 작업의 내용이 달라 원래 보관본을 유지했어요.");
            return export(context,record,state,guard);
        }
        if(body.exists()) throw new IOException("이전 임시 저장 결과가 불확실해 자동으로 덮어쓰지 않았어요.");
        MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0;
        try(OutputStream raw=Files.newOutputStream(body.toPath(),java.nio.file.StandardOpenOption.CREATE_NEW,java.nio.file.StandardOpenOption.WRITE);FileOutputStream sync=new FileOutputStream(body,true)) {
            byte[] buffer=new byte[65536];int n;
            while(true){guard.run();n=source.read(buffer);guard.run();if(n<0)break;if(n==0)continue;count+=n;if(count>MAX_BYTES)throw new IOException("미디어가 2GB를 넘어 저장을 중단했어요.");raw.write(buffer,0,n);digest.update(buffer,0,n);}
            raw.flush();sync.getFD().sync();
        }
        MigrationLedger.syncDirectory(dir);guard.run();
        JSONObject state=new JSONObject().put("version",1).put("id",id).put("category",category).put("name",name).put("mime",mime)
            .put("bytes",count).put("sha256",FileExplorerRepository.hex(digest.digest())).put("state","prepared");
        write(record,state);
        try{return export(context,record,state,guard);}
        catch(Exception failure){throw new IOException("미디어 보관본은 앱 내부에 남겼어요. 저장 위치의 대기 파일 저장에서 확인해 주세요. "+failure.getMessage(),failure);}
    }
    /** Explicit continuation of the same media job. No remote re-download if a staged result exists. */
    static synchronized Uri resume(Context context,String key,Runnable guard)throws Exception {
        File record=new File(directory(context),id(key)+".json");
        if(!record.exists()&&!new File(record+".bak").exists()){
            if(new File(record.getParentFile(),id(key)+".data").exists())throw new IOException("미완성 미디어 보관본이 있어 자동 재다운로드·재저장하지 않아요. 저장 위치에서 확인 필요 항목으로 남겨 두었어요.");
            return null;
        }
        JSONObject state=read(record);validateState(state,id(key));return export(context,record,state,guard);
    }
    /** Drops the private staging copy and record of a verified 백업 export; the saved file stays. Media keep theirs. */
    static synchronized void discard(Context context,String key)throws Exception {
        String id=id(key);File dir=directory(context),record=new File(dir,id+".json");JSONObject state=read(record);validateState(state,id);
        if(!"백업".equals(state.getString("category"))||!"verified".equals(state.getString("state")))throw new IOException("확인된 백업 보관본만 정리해요.");
        // The copy goes first: a record left without it is verified and inert, an orphan copy would read as unfinished.
        Files.deleteIfExists(new File(dir,id+".data").toPath());new AtomicFile(record).delete();MigrationLedger.syncDirectory(dir);
    }
    static int pendingCount(Context context) {
        File dir=new File(context.getFilesDir(),DIRECTORY);int count=orphanCount(dir);
        for(File row:records(dir))try{if(!"verified".equals(read(row).optString("state")))count++;}catch(Exception malformed){count++;}
        return count;
    }
    /** Only prepared records can start a new public write. Uncertain/orphan records remain visible. */
    static synchronized String exportPending(Context context,Runnable guard)throws Exception {
        File dir=directory(context);List<File> rows=records(dir);int saved=0,orphans=orphanCount(dir),held=orphans;
        for(File row:rows){guard.run();try{JSONObject state=read(row);if("verified".equals(state.optString("state")))continue;if(!"prepared".equals(state.optString("state"))){held++;continue;}export(context,row,state,guard);saved++;}catch(Exception error){guard.run();held++;}}
        return "미디어 "+saved+"개 저장·검증, "+held+"개 보류(임시 보관 중 중단·확인 필요 "+orphans+"개 포함). 새 들퍼레 폴더에서 확인할 수 있어요. 원래 작업의 갤러리 연결은 작업을 다시 확인할 때 완료돼요. 앱 내부 보관본은 유지해요.";
    }
    private static List<File> records(File dir){
        File[] files=dir.listFiles();SortedMap<String,File> rows=new TreeMap<>();
        if(files!=null)for(File file:files){String name=file.getName();if(name.matches("[a-f0-9]{64}\\.json(?:\\.bak)?")){String id=name.substring(0,64);rows.put(id,new File(dir,id+".json"));}}
        return List.copyOf(rows.values());
    }
    private static int orphanCount(File dir){
        File[] files=dir.listFiles();int count=0;if(files!=null)for(File file:files){String name=file.getName();if(name.matches("[a-f0-9]{64}\\.data")){String id=name.substring(0,64);if(!new File(dir,id+".json").exists()&&!new File(dir,id+".json.bak").exists())count++;}}return count;
    }

    private static Uri export(Context context,File record,JSONObject state,Runnable guard)throws Exception {
        validateState(state,record.getName().substring(0,64));guard.run();File body=new File(record.getParentFile(),state.getString("id")+".data");
        if(Files.isSymbolicLink(body.toPath())||!body.isFile()||body.length()!=state.getLong("bytes"))throw new IOException("미디어 보관본의 위치·크기가 달라요.");
        try(InputStream in=new FileInputStream(body)){if(!digest(in,guard).equals(state.getString("sha256")))throw new IOException("미디어 보관본 검증에 실패했어요.");}
        if("verified".equals(state.getString("state"))){Uri output=Uri.parse(state.getString("uri"));check(context,Uri.parse(state.getString("tree")),output,guard);verify(context,output,state,guard);MediaIndex.register(context,output,state.getString("mime"));return output;}
        if(!"prepared".equals(state.getString("state")))throw new IOException("미디어 저장 결과가 불확실해 자동으로 다시 쓰지 않아요. 앱 내부 보관본과 미완성 파일을 유지했어요.");
        Uri tree=SharedOutputFolder.selectedTree(context);String root=DocumentsContract.getTreeDocumentId(tree);Uri rootUri=DocumentsContract.buildDocumentUriUsingTree(tree,root);
        check(context,tree,rootUri,guard);String category=state.getString("category"), folderId=root+"/"+category;Uri folder=null;
        for(Row row:list(context,tree,root,guard))if(category.equals(row.name())){if(!folderId.equals(row.id())||!DocumentsContract.Document.MIME_TYPE_DIR.equals(row.mime()))throw new IOException("미디어 하위 폴더의 위치가 잘못됐어요.");folder=DocumentsContract.buildDocumentUriUsingTree(tree,row.id());}
        if(folder==null){check(context,tree,rootUri,guard);folder=DocumentsContract.createDocument(context.getContentResolver(),rootUri,DocumentsContract.Document.MIME_TYPE_DIR,category);}
        if(folder==null)throw new IOException("미디어 폴더를 만들지 못했어요.");check(context,tree,folder,guard);
        if(!folderId.equals(DocumentsContract.getDocumentId(folder)))throw new IOException("다른 위치에 만들어져 미디어 쓰기를 중단했어요.");
        Set<String> names=new HashSet<>(),ids=new HashSet<>();for(Row row:list(context,tree,folderId,guard)){names.add(row.name());ids.add(row.id());}
        String name=state.getString("name");if(names.contains(name)){int dot=name.lastIndexOf('.');String suffix="-"+state.getString("id").substring(0,12);name=dot>0?name.substring(0,dot)+suffix+name.substring(dot):name+suffix;if(names.contains(name))throw new IOException("같은 이름의 파일이 있어 덮어쓰지 않았어요.");}
        FileOrganizationPlan.safeName(name);check(context,tree,folder,guard);
        state.put("state","creating").put("tree",tree.toString()).put("outputName",name);write(record,state);check(context,tree,folder,guard);
        Uri output=DocumentsContract.createDocument(context.getContentResolver(),folder,state.getString("mime"),name);
        if(output==null)throw new IOException("새 미디어 파일을 만들지 못했어요.");
        state.put("uri",output.toString()).put("state","created");write(record,state);check(context,tree,output,guard);
        String outputId=DocumentsContract.getDocumentId(output);
        if(!outputId.equals(folderId+"/"+name)||ids.contains(outputId))throw new IOException("새 미디어 파일의 위치를 확인하지 못해 쓰지 않았어요.");
        Row observed=metadata(context,output);if(!outputId.equals(observed.id())||!name.equals(observed.name())||!state.getString("mime").equals(observed.mime())||observed.size()!=0)throw new IOException("빈 새 미디어 파일로 확인되지 않아 쓰지 않았어요.");
        check(context,tree,output,guard);state.put("state","copying");write(record,state);check(context,tree,output,guard);
        ParcelFileDescriptor descriptor=context.getContentResolver().openFileDescriptor(output,"w");if(descriptor==null)throw new IOException("새 미디어 파일을 열지 못했어요.");
        try(InputStream in=new FileInputStream(body);ParcelFileDescriptor.AutoCloseOutputStream out=new ParcelFileDescriptor.AutoCloseOutputStream(descriptor)) {
            byte[] buffer=new byte[65536];int n;while(true){check(context,tree,output,guard);n=in.read(buffer);if(n<0)break;check(context,tree,output,guard);out.write(buffer,0,n);check(context,tree,output,guard);}out.flush();check(context,tree,output,guard);out.getFD().sync();
        }
        check(context,tree,output,guard);verify(context,output,state,guard);check(context,tree,output,guard);
        state.put("state","verified");write(record,state);guard.run();
        // Verified and kept: let Android's media index list it, so galleries and other apps' photo pickers can attach it.
        MediaIndex.register(context,output,state.getString("mime"));return output;
    }
    private record Row(String id,String name,String mime,long size){}
    private static List<Row> list(Context context,Uri tree,String parent,Runnable guard)throws Exception {
        List<Row> rows=new ArrayList<>();Uri doc=DocumentsContract.buildDocumentUriUsingTree(tree,parent);check(context,tree,doc,guard);
        try(Cursor c=context.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(tree,parent),new String[]{"document_id","_display_name","mime_type","_size"},null,null,null)){
            if(c==null)throw new IOException("미디어 폴더를 읽지 못했어요.");while(c.moveToNext()){check(context,tree,doc,guard);if(rows.size()>=2000)throw new IOException("미디어 폴더의 확인 한도 2,000개에 도달해 쓰지 않았어요.");Row row=row(c);FileOrganizationPlan.safeName(row.name());if(!row.id().equals(parent+"/"+row.name()))throw new IOException("하위 파일 이름과 위치가 다르게 응답했어요.");rows.add(row);}}
        return rows;
    }
    private static Row metadata(Context context,Uri uri)throws Exception {try(Cursor c=context.getContentResolver().query(uri,new String[]{"document_id","_display_name","mime_type","_size"},null,null,null)){if(c==null||!c.moveToFirst())throw new IOException("저장 파일을 확인하지 못했어요.");Row result=row(c);if(c.moveToNext())throw new IOException("저장 파일 응답이 모호해요.");return result;}}
    private static Row row(Cursor c)throws IOException{if(c.isNull(0)||c.isNull(1)||c.isNull(2))throw new IOException("파일 메타데이터가 불완전해요.");return new Row(c.getString(0),c.getString(1),c.getString(2),c.isNull(3)?-1:c.getLong(3));}
    private static void verify(Context context,Uri output,JSONObject state,Runnable guard)throws Exception {
        Uri tree=Uri.parse(state.getString("tree"));check(context,tree,output,guard);Row row=metadata(context,output);
        if(!DocumentsContract.getDocumentId(output).equals(row.id())||!state.getString("outputName").equals(row.name())||!state.getString("mime").equals(row.mime())||row.size()!=state.getLong("bytes"))throw new IOException("저장된 미디어의 위치·크기가 달라 완료하지 않았어요.");
        FileExplorerRepository repo=new FileExplorerRepository(context,tree);String hash=repo.hash(output,MAX_BYTES,()->{guard.run();return false;});
        if(!state.getString("sha256").equals(hash))throw new IOException("미디어 내용 검증에 실패했어요. 보관본과 미완성 파일을 유지했어요.");check(context,tree,output,guard);
    }
    private static void check(Context context,Uri tree,Uri output,Runnable guard)throws Exception{guard.run();if(!tree.equals(SharedOutputFolder.selectedTree(context)))throw new IOException("저장 위치가 바뀌어 미디어 저장을 중단했어요.");SharedOutputFolder.requireContentAccess(context,output);guard.run();}
    private static void validate(String category,String name,String mime)throws IOException{FileOrganizationPlan.safeName(name);if(!Set.of("이미지","영상","오디오","백업",CAPTURES,AUDIO).contains(category)||mime==null||!((category.equals("이미지")||category.equals(CAPTURES))&&Set.of("image/png","image/jpeg","image/webp").contains(mime)||category.equals("영상")&&Set.of("video/mp4","video/quicktime","video/webm","video/x-matroska","video/3gpp").contains(mime)||(category.equals("오디오")||category.equals(AUDIO))&&Set.of("audio/wav","audio/mpeg","audio/mp4").contains(mime)||category.equals("백업")&&Set.of("application/json","text/markdown").contains(mime)))throw new IOException("지원하지 않는 미디어 저장 종류예요.");}
    private static void validateState(JSONObject state,String id)throws Exception{if(state.getInt("version")!=1||!id.equals(state.getString("id"))||!state.getString("sha256").matches("[a-f0-9]{64}")||state.getLong("bytes")<0||state.getLong("bytes")>MAX_BYTES||!Set.of("prepared","creating","created","copying","verified").contains(state.getString("state")))throw new IOException("미디어 저장 기록을 확인하지 못했어요.");validate(state.getString("category"),state.getString("name"),state.getString("mime"));}
    private static String id(String key)throws Exception{if(key==null||key.isBlank()||key.length()>1024)throw new IOException("미디어 작업 식별자가 없어요.");return FileExplorerRepository.hex(MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8)));}
    private static String digest(InputStream in,Runnable guard)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0;byte[] buffer=new byte[65536];int n;while(true){guard.run();n=in.read(buffer);guard.run();if(n<0)break;if(n==0)continue;count+=n;if(count>MAX_BYTES)throw new IOException("미디어가 2GB를 넘어요.");digest.update(buffer,0,n);}return FileExplorerRepository.hex(digest.digest());}
    private static File directory(Context context)throws IOException{File dir=new File(context.getFilesDir(),DIRECTORY);if(Files.isSymbolicLink(dir.toPath()))throw new IOException("미디어 보관 폴더가 바뀌었어요.");if(!dir.isDirectory()){if(!dir.mkdir())throw new IOException("미디어 임시 보관 폴더를 만들지 못했어요.");MigrationLedger.syncDirectory(dir.getParentFile());}return dir;}
    private static JSONObject read(File file)throws Exception{for(String suffix:List.of("",".bak",".new"))if(Files.isSymbolicLink(new File(file+suffix).toPath()))throw new IOException("미디어 기록의 링크는 읽지 않아요.");try(InputStream in=new AtomicFile(file).openRead()){byte[] bytes=in.readNBytes(32769);if(bytes.length>32768)throw new IOException("미디어 기록이 너무 커요.");return new JSONObject(new String(bytes,StandardCharsets.UTF_8));}}
    private static void write(File file,JSONObject state)throws Exception{for(String suffix:List.of("",".bak",".new"))if(Files.isSymbolicLink(new File(file+suffix).toPath()))throw new IOException("미디어 기록의 링크에는 쓰지 않아요.");AtomicFile atomic=new AtomicFile(file);FileOutputStream out=null;try{out=atomic.startWrite();out.write(state.toString().getBytes(StandardCharsets.UTF_8));out.flush();out.getFD().sync();atomic.finishWrite(out);out=null;MigrationLedger.syncDirectory(file.getParentFile());if(!read(file).toString().equals(state.toString()))throw new IOException("미디어 기록 저장을 확인하지 못했어요.");}catch(Exception error){if(out!=null)atomic.failWrite(out);throw error;}}
}
